function Dde() {
	let e = [];
	for (let t of [
		1,
		2,
		3
	]) Ede[t].forEach((n, r) => {
		let i = [];
		n.forEach(([e, t, n], r) => {
			let a = r % 2 == 0;
			i.push(a ? {
				slot: `(${e.toString()} + ${t.toString()}) × ${n.toString()}`,
				card: ((e + t) * n).toString()
			} : {
				slot: `${e.toString()} + ${t.toString()} × ${n.toString()}`,
				card: (e + t * n).toString()
			});
		});
		let a = new Set(i.map((e) => e.card));
		if (a.size !== i.length) throw Error(`duplicate values in bracket-or-not-match ${t.toString()}/${r.toString()}`);
		let [o, s, c] = n[0], l = (o + s * c).toString();
		e.push(lM({
			level: t,
			prompt: {
				en: "Work out each expression and match it to its value. Brackets change the order!",
				fr: "Calcule chaque expression et associe-la à sa valeur. Les parenthèses changent l'ordre !"
			},
			pairs: i,
			spare: a.has(l) ? [] : [{
				id: "z1",
				glyph: l
			}],
			hint: Xue.value,
			seed: z(t, r, 2114)
		}));
	});
	return e;
}
